INSERT INTO repo_kprs (kpr_id, name, domain, discipline, principle_type, principle_granularity, definition, scope, core_ideas, semantic_description, keywords_synonyms, status) VALUES ('KPR_000051', 'Principle of Superposition in Linear Circuits', 'Engineering & Technology', 'Electrical Engineering', 'Principle', 'Atomic', 'In a linear electrical network, the response produced by multiple independent sources equals the sum of responses produced by each source acting alone, with other independent sources deactivated appropriately.', 'Requires linear circuit elements and linear operating conditions; dependent sources remain active according to the circuit model.', 'Linearity; independent sources; additive response; circuit analysis', 'The circuit form of superposition supports decomposition of linear network responses into source-by-source contributions.', 'Circuit superposition theorem; Linearity; independent sources; additive response; circuit analysis', 'Active'), ('KPR_000052', 'Thevenin Equivalence Principle', 'Engineering & Technology', 'Electrical Engineering', 'Theorem', 'Atomic', 'Any linear two-terminal network can be represented at its terminals by an equivalent voltage source in series with an equivalent resistance or impedance.', 'Applies to linear two-terminal networks and the selected terminal conditions; nonlinear networks require an appropriate local or nonlinear equivalent treatment.', 'Two-terminal network; equivalent source; Thevenin voltage; Thevenin resistance', 'Thevenin equivalence reduces a linear network to a compact source-load representation for analysis and design.', 'Thevenin theorem; Thevenin equivalent', 'Active'), ('KPR_000053', 'Norton''s Equivalence Principle', 'Engineering & Technology', 'Electrical Engineering', 'Theorem', 'Atomic', 'Any linear two-terminal network can be represented by an equivalent current source in parallel with an equivalent resistance or impedance.', 'Applies to linear two-terminal networks under the adopted circuit model.', 'Two-terminal network; equivalent current source; Norton current; Norton resistance', 'Any linear two-terminal network can be represented by an equivalent current source in parallel with an equivalent resistance or impedance. Its valid use is bounded by: Applies to linear two-terminal networks under the adopted circuit model. Key ideas include Two-terminal network; equivalent current source; Norton current; Norton resistance.', 'Norton theorem; Norton equivalent', 'Active'), ('KPR_000055', 'Precautionary Principle', 'Law', 'Environmental Law', 'Normative Principle', 'Atomic', 'Where there are plausible risks of serious or irreversible environmental harm, lack of full scientific certainty should not automatically be used as a reason to postpone proportionate preventive measures.', 'Applies to environmental decision-making under scientific uncertainty and must be interpreted with the legal threshold, proportionality, evidence, and procedural requirements of the governing legal regime.', 'Scientific uncertainty; prevention; serious harm; proportionality', 'The precautionary principle guides decisions where environmental risk may be significant but scientific evidence remains incomplete.', 'Precautionary principle; precaution', 'Active'), ('KPR_000056', 'Polluter Pays Principle', 'Law', 'Environmental Law', 'Normative Principle', 'Atomic', 'The polluter pays principle assigns the costs of preventing, controlling, and remedying pollution to the party responsible for the pollution, subject to the applicable legal framework.', 'Applies as a legal/policy principle within the relevant jurisdiction and does not automatically determine every question of liability, compensation, or causation.', 'Polluter responsibility; prevention costs; remediation; environmental liability', 'The principle supports allocation of pollution-control and remediation costs to responsible actors.', 'Polluter pays principle; polluter pays', 'Active'), ('KPR_000057', 'Sustainable Development Principle', 'Law', 'Environmental Law; Climate Change Law', 'Normative Principle', 'Atomic', 'The sustainable development principle requires decision-making to balance present development needs with the protection of environmental and social conditions needed for future generations.', 'Applies as a legal and governance principle subject to the constitutional, statutory, and judicial framework of the jurisdiction; it does not prescribe a single universal balancing formula.', 'Intergenerational equity; development; environmental protection; balancing', 'The principle frames development decisions as requiring integration of economic, social, and environmental considerations.', 'Sustainable development principle; sustainable development', 'Active'), ('KPR_000058', 'Public Trust Doctrine', 'Law', 'Environmental Law', 'Legal Doctrine', 'Atomic', 'The public trust doctrine holds that certain natural resources are subject to public-interest obligations and cannot be treated solely as ordinary private assets where the doctrine applies.', 'Applies to resources and circumstances recognized by the governing legal system; the precise scope of trusteeship and remedies is jurisdiction-specific.', 'Public resources; trusteeship; public interest; natural resources', 'The doctrine constrains state or resource-management decisions by recognizing duties associated with resources held for public benefit.', 'Public trust doctrine; public trust', 'Active'), ('KPR_000059', 'Intergenerational Equity Principle', 'Law', 'Environmental Law; Climate Change Law', 'Normative Principle', 'Atomic', 'Environmental decision-making should account for the rights and interests of future generations when present actions can impose long-lived environmental costs or reduce future options.', 'Applies where recognized in the governing legal or policy framework; it does not require all present benefits to be rejected in favour of future interests.', 'Future generations; long-term impacts; environmental inheritance; equity', 'Intergenerational equity introduces a temporal dimension to environmental governance and sustainability decisions.', 'Intergenerational equity; equity across generations', 'Active'), ('KPR_000060', 'Common but Differentiated Responsibilities Principle', 'Law', 'Climate Change Law', 'Normative Principle', 'Atomic', 'States share responsibility for addressing global environmental problems while their responsibilities can differ according to relevant circumstances, including historical contribution and capacity, as recognized in the applicable regime.', 'Applies within the specific international environmental or climate regime in which the principle is invoked; its legal effect depends on the treaty and negotiating context.', 'Common responsibility; differentiation; historical contribution; capacity', 'CBDR provides a normative basis for differentiated responsibilities in international environmental and climate governance.', 'CBDR; common but differentiated responsibilities', 'Active'), ('KPR_000061', 'No-Harm Principle', 'Law', 'Environmental Law; Climate Change Law', 'Normative Principle', 'Atomic', 'States should ensure that activities within their jurisdiction or control do not cause significant environmental damage to other states or areas beyond national jurisdiction, subject to the applicable international legal framework.', 'Applies to transboundary environmental harm and is interpreted through the relevant customary and treaty law; significance and due-diligence requirements are context-dependent.', 'Transboundary harm; due diligence; territorial jurisdiction; environmental impact', 'The no-harm principle establishes a foundational constraint on activities that may cause significant transboundary environmental damage.', 'No-harm rule; transboundary harm principle', 'Unlinked'), ('KPR_000062', 'Environmental Participation Principle', 'Law', 'Environmental Law; Public Policy', 'Normative Principle', 'Atomic', 'Affected people and stakeholders should have meaningful opportunities to participate in environmental decision-making, subject to the governing legal and procedural framework.', 'Applies to participation processes recognized by law or policy; participation does not necessarily imply a veto over the final decision.', 'Access to information; participation; consultation; procedural fairness', 'Participation strengthens procedural legitimacy and can improve the information available to environmental decision-makers.', 'Participation principle; public participation', 'Active'), ('KPR_000063', 'Rule of Law', 'Law', 'Law', 'Normative Principle', 'Atomic', 'Public and private actors are governed by publicly established law, with legal accountability, procedural fairness, and limits on arbitrary exercise of power.', 'Applies as a constitutional and legal governance principle whose precise institutional requirements depend on the jurisdiction.', 'Legality; accountability; predictability; equality before law; judicial review', 'The rule of law provides a foundational governance principle for lawful, reviewable, and non-arbitrary exercise of authority.', 'Rule of law; legality principle', 'Active'), ('KPR_000064', 'Principle of Natural Justice', 'Law', 'Law', 'Normative Principle', 'Atomic', 'Natural justice requires fair decision-making procedures, commonly including an opportunity to be heard and an impartial decision-maker, subject to the governing legal framework.', 'Applies to administrative, disciplinary, and other decision contexts where procedural fairness is required; content varies with the statutory and factual setting.', 'Audi alteram partem; impartiality; hearing; procedural fairness', 'Natural justice provides a foundational standard for fair administrative and adjudicative procedures.', 'Natural justice; procedural fairness', 'Active'), ('KPR_000065', 'Principle of Proportionality', 'Law', 'Law; Public Policy', 'Normative Principle', 'Atomic', 'A public measure restricting a protected interest should bear a rational and proportionate relationship to a legitimate objective, with the intensity of review determined by the applicable legal framework.', 'Applies within the relevant constitutional or administrative-law test; the elements of proportionality differ across jurisdictions and legal contexts.', 'Legitimate aim; suitability; necessity; balancing', 'Proportionality structures judicial or administrative review of measures that affect protected rights or interests.', 'Proportionality principle; proportionality test', 'Unlinked'), ('KPR_000066', 'Pacta Sunt Servanda', 'Law', 'Contract Law', 'Legal Doctrine', 'Atomic', 'A validly formed contract is to be performed in good faith according to its agreed terms, subject to applicable law and recognized grounds for modification or avoidance.', 'Applies to binding agreements within the governing contract-law regime; mandatory law, impossibility, illegality, and recognized doctrines can qualify performance obligations.', 'Binding agreement; performance; good faith; contractual obligation', 'The doctrine underpins contractual reliability by treating agreed obligations as legally significant commitments.', 'Pacta sunt servanda; agreements must be kept', 'Active'), ('KPR_000067', 'Contra Proferentem Principle', 'Law', 'Contract Law', 'Legal Doctrine', 'Atomic', 'Where an ambiguous contractual term remains unresolved under the applicable interpretive rules, the ambiguity may be construed against the party responsible for drafting the term.', 'Applies only where the governing legal system recognizes the doctrine and where ambiguity remains after applicable interpretive principles have been considered.', 'Contract interpretation; ambiguity; drafting party; allocation of uncertainty', 'The principle allocates unresolved drafting ambiguity against the party that introduced the wording in contexts where the doctrine applies.', 'Contra proferentem; Contract interpretation; ambiguity; drafting party; allocation of uncertainty', 'Active'), ('KPR_000068', 'Separate Legal Personality Doctrine', 'Law', 'Corporate Law', 'Legal Doctrine', 'Atomic', 'A corporation has a legal personality distinct from its shareholders or members, so corporate rights and liabilities are ordinarily separate from those of the individuals behind the entity.', 'Applies to incorporated entities subject to statutory exceptions, including circumstances in which courts or legislation permit attribution, lifting of the corporate veil, or direct liability.', 'Corporate personality; separate entity; shareholder liability; veil', 'Separate legal personality provides the foundational legal structure for corporate rights, obligations, ownership, and liability.', 'Separate legal personality; corporate personality', 'Active'), ('KPR_000069', 'Fiduciary Duty Principle', 'Law', 'Corporate Law', 'Legal Doctrine', 'Atomic', 'A fiduciary must exercise entrusted power for proper purposes and with the loyalty, care, and conflict-management obligations imposed by the applicable legal regime.', 'Applies only where a fiduciary relationship or statutory fiduciary duty exists; exact duties vary by role and jurisdiction.', 'Loyalty; conflicts of interest; proper purpose; trust; duty of care', 'Fiduciary duties constrain the use of entrusted power and protect beneficiaries, principals, shareholders, or other legally protected interests.', 'Fiduciary duty; duty of loyalty', 'Active'), ('KPR_000070', 'Principle of Informed Consent', 'Social Science', 'Social Science; Research Methods', 'Normative Principle', 'Atomic', 'Participation in research should be voluntary and based on adequate information about the study, material risks, potential benefits, and participant rights.', 'Applies to human-subject research subject to the applicable ethics framework; consent requirements may be modified only under recognized ethical and regulatory conditions.', 'Voluntariness; disclosure; autonomy; participant rights', 'Informed consent protects participant autonomy and supports ethically valid participation in research.', 'Informed consent; consent principle', 'Active'), ('KPR_000071', 'Principle of Respect for Persons', 'Social Science', 'Social Science; Research Methods', 'Normative Principle', 'Atomic', 'Research should respect individuals as autonomous agents and provide additional protections for people with diminished autonomy.', 'Applies to human-subject research and requires assessment of autonomy, vulnerability, and appropriate protections.', 'Autonomy; vulnerability; protection; voluntary participation', 'Respect for persons is a foundational research-ethics principle underlying informed consent and additional safeguards for vulnerable participants.', 'Respect for persons; autonomy principle', 'Active'), ('KPR_000072', 'Principle of Beneficence', 'Social Science', 'Social Science; Research Methods', 'Normative Principle', 'Atomic', 'Research should seek to maximize reasonably expected benefits and minimize foreseeable harms to participants and affected groups.', 'Applies to ethical research planning and requires context-specific assessment of risks, benefits, alternatives, and mitigation measures.', 'Risk-benefit assessment; harm minimization; benefit maximization', 'Beneficence provides a framework for evaluating whether research risks are justified by anticipated benefits and whether harms can be reduced.', 'Beneficence; risk-benefit principle', 'Active'), ('KPR_000073', 'Principle of Justice in Research', 'Social Science', 'Social Science; Research Methods', 'Normative Principle', 'Atomic', 'The burdens and benefits of research should be distributed fairly, with participant selection and inclusion justified by the research question rather than convenience or exploitation.', 'Applies to participant selection, access, compensation, and distribution of research burdens and benefits under the relevant ethical framework.', 'Fair selection; distribution; inclusion; exploitation', 'The justice principle addresses fairness in who bears research risks and who can benefit from research participation.', 'Research justice; justice principle', 'Active'), ('KPR_000074', 'Principle of Evidence-Based Policy', 'Social Science', 'Public Policy and Governance', 'Principle', 'Atomic', 'Policy decisions should systematically use the best available relevant evidence while explicitly accounting for uncertainty, values, feasibility, and distributional consequences.', 'Applies to policy formulation and evaluation; evidence is one input to decision-making and does not eliminate legitimate value judgments or political choices.', 'Evidence; uncertainty; evaluation; policy design; implementation', 'Evidence-based policy improves the traceability of policy reasoning by distinguishing empirical claims from values, assumptions, and implementation constraints.', 'Evidence-based policymaking; evidence-informed policy', 'Active'), ('KPR_000075', 'Principle of Transparency', 'Social Science', 'Public Policy and Governance', 'Normative Principle', 'Atomic', 'Public institutions should make decision-relevant information sufficiently accessible, clear, and timely to permit understanding and scrutiny, subject to legitimate confidentiality limits.', 'Applies to public governance and disclosure systems within the applicable legal framework; transparency does not require unrestricted disclosure of protected information.', 'Disclosure; accessibility; clarity; public scrutiny', 'Transparency supports accountability by enabling stakeholders to understand decisions, processes, resource use, and performance.', 'Transparency principle; openness', 'Active'), ('KPR_000076', 'Principle of Accountability', 'Social Science', 'Public Policy and Governance', 'Normative Principle', 'Atomic', 'Actors entrusted with public authority or resources should explain and justify their decisions and remain subject to appropriate oversight and consequences.', 'Applies to the institutional roles and accountability mechanisms established by the relevant governance framework.', 'Answerability; oversight; justification; consequences', 'Actors entrusted with public authority or resources should explain and justify their decisions and remain subject to appropriate oversight and consequences. Its valid use is bounded by: Applies to the institutional roles and accountability mechanisms established by the relevant governance framework. Key ideas include Answerability; oversight; justification; consequences.', 'Accountability principle; public accountability', 'Active'), ('KPR_000077', 'Principle of Participation', 'Social Science', 'Public Policy and Governance', 'Normative Principle', 'Atomic', 'People affected by public decisions should have meaningful opportunities to contribute information, preferences, or deliberative input through appropriate processes.', 'Applies to participatory governance mechanisms appropriate to the decision context; participation does not necessarily confer decision rights.', 'Stakeholder participation; consultation; deliberation; inclusion', 'Participation improves procedural legitimacy and can contribute local knowledge and diverse perspectives to policy decisions.', 'Participation principle; participatory governance', 'Active'), ('KPR_000078', 'Opportunity-Cost Principle', 'Social Science', 'Development Economics', 'Principle', 'Atomic', 'The opportunity cost of choosing an option is the value of the best feasible alternative forgone.', 'Applies when alternatives are mutually constrained by scarce resources, time, or other decision limits; the relevant opportunity cost depends on the feasible choice set.', 'Scarcity; trade-off; alternative forgone; resource allocation', 'Opportunity cost provides the basic decision principle for reasoning about trade-offs under scarcity.', 'Opportunity cost; cost of forgone alternative', 'Active'), ('KPR_000079', 'Principle of Diminishing Marginal Returns', 'Social Science', 'Development Economics', 'Principle', 'Atomic', 'Holding other relevant inputs fixed, successive additions of a variable input eventually produce smaller increments in output under the conditions of the production model.', 'Applies to the specified production function and input regime; it does not imply that total output necessarily decreases when the variable input rises.', 'Marginal product; fixed input; variable input; production', 'Diminishing marginal returns explains why the marginal contribution of an input can decline as its use expands while other inputs remain constrained.', 'Diminishing marginal returns; diminishing marginal product', 'Active'), ('KPR_000080', 'Principle of Comparative Advantage', 'Social Science', 'Development Economics', 'Principle', 'Atomic', 'An agent has comparative advantage in an activity when it can perform that activity at a lower opportunity cost than another agent.', 'Applies to comparative-cost analysis with clearly defined alternatives and opportunity costs; it is distinct from absolute advantage.', 'Opportunity cost; specialization; trade; relative productivity', 'Comparative advantage provides the economic principle explaining why specialization and exchange can create gains from trade even when productivity differs.', 'Comparative advantage; comparative-cost principle', 'Active'), ('KPR_000081', 'Principle of Methodological Transparency', 'Social Science', 'Social Science; Research Methods', 'Principle', 'Atomic', 'Research methods, decisions, data-processing steps, analytical procedures, and relevant limitations should be documented sufficiently for others to understand how conclusions were produced.', 'Applies to empirical research and requires disclosure proportionate to the method, data sensitivity, and ethical constraints; it does not require disclosure of protected personal or proprietary information.', 'Reproducibility; documentation; analytic decisions; limitations', 'Research methods, decisions, data-processing steps, analytical procedures, and relevant limitations should be documented sufficiently for others to understand how conclusions were produced. Its valid use is bounded by: Applies to empirical research and requires disclosure proportionate to the method, data sensitivity, and ethical constraints; it does not require disclosure of protected personal or proprietary information. Key ideas include Reproducibility; documentation; analytic decisions; limitations.', 'Methodological transparency; transparent reporting', 'Active'), ('KPR_000082', 'Principle of Measurement Validity', 'Social Science', 'Social Science; Research Methods', 'Principle', 'Atomic', 'A measurement or operationalization should adequately represent the construct it is intended to measure within the stated theoretical and empirical context.', 'Applies to operational definitions and measurement instruments; validity is evidence-based and context-specific rather than a permanent intrinsic property of an instrument.', 'Construct validity; operationalization; measurement evidence', 'Measurement validity links abstract constructs to observable indicators and supports defensible interpretation of research measures.', 'Validity principle; measurement validity', 'Active'), ('KPR_000083', 'Newton''s First Law of Motion', 'Engineering & Technology', 'Mechanical Engineering; Civil Engineering', 'Law', 'Atomic', 'A body remains at rest or in uniform straight-line motion unless acted upon by a nonzero net external force.', 'Applies in inertial reference frames and defines the force-free motion assumed in classical mechanics.', 'Inertia; inertial frame; uniform motion; net force', 'Newton''s first law establishes inertial motion and provides the conceptual basis for identifying inertial reference frames and interpreting force as a cause of changes in motion.', 'Newton''s first law; law of inertia', 'Unlinked'), ('KPR_000084', 'Work-Energy Principle', 'Engineering & Technology', 'Mechanical Engineering; Civil Engineering', 'Principle', 'Atomic', 'The net work done by forces on a body equals the change in its kinetic energy.', 'Applies to the adopted mechanical system and force/path representation; potential and nonconservative effects must be accounted for consistently.', 'Work; kinetic energy; force; energy transfer', 'The work-energy principle converts force and motion information into an energy relation and can simplify dynamics problems where time is not the primary variable.', 'Work-energy theorem; work-energy principle', 'Unlinked'), ('KPR_000085', 'Conservation of Angular Momentum', 'Engineering & Technology', 'Mechanical Engineering', 'Conservation Principle', 'Atomic', 'The angular momentum of a system changes only through the net external moment about the selected reference point or axis.', 'Applies to a clearly defined system and reference point/axis with all relevant external moments and angular-momentum fluxes accounted for.', 'Angular momentum; external moment; rotational dynamics; system boundary', 'Angular-momentum conservation governs rotational dynamics and supports analysis of gyroscopic motion, rotors, and isolated rotating systems.', 'Angular momentum conservation; rotational conservation law', 'Active'), ('KPR_000086', 'Rational-Agent Principle', 'Engineering & Technology', 'Artificial Intelligence', 'Principle', 'Atomic', 'An intelligent agent should select actions that maximize expected performance according to its objectives and available information.', 'Applies to agents making decisions under specified objectives, percepts, actions, and environmental uncertainty; it does not imply perfect rationality or omniscience.', 'objective-directed action; percepts; expected performance; limited information', 'An intelligent agent should select actions that maximize expected performance according to its objectives and available information. Its valid use is bounded by: Applies to agents making decisions under specified objectives, percepts, actions, and environmental uncertainty; it does not imply perfect rationality or omniscience. Key ideas include objective-directed action; percepts; expected performance; limited information.', 'rational action; rational agent; expected utility; agent rationality', 'Active'), ('KPR_000087', 'Heuristic Dominance Principle', 'Engineering & Technology', 'Artificial Intelligence', 'Principle', 'Atomic', 'A more informative admissible heuristic can reduce search effort without sacrificing optimality in algorithms such as A*.', 'Applies to heuristic search when heuristic admissibility and consistency conditions are satisfied.', 'heuristic informativeness; admissibility; search effort; optimality', 'Relates heuristic quality to the number of states explored while preserving solution guarantees under stated conditions.', 'heuristic dominance; admissible heuristic; A*', 'Active'), ('KPR_000088', 'Bayesian Decision Principle', 'Engineering & Technology', 'Artificial Intelligence', 'Principle', 'Atomic', 'Decisions under uncertainty should combine prior beliefs, observed evidence, and utilities to select actions with highest expected utility.', 'Applies to probabilistic decision problems with explicit beliefs and utility models.', 'prior; evidence; posterior; utility; expected utility', 'Decisions under uncertainty should combine prior beliefs, observed evidence, and utilities to select actions with highest expected utility. Its valid use is bounded by: Applies to probabilistic decision problems with explicit beliefs and utility models. Key ideas include prior; evidence; posterior; utility; expected utility.', 'Bayesian decision theory; expected utility', 'Active'), ('KPR_000089', 'Empirical Risk Minimization Principle', 'Engineering & Technology', 'Machine Learning', 'Principle', 'Atomic', 'A learning algorithm can select a model by minimizing empirical loss over observed training data, subject to the assumptions and regularization used.', 'Applies to supervised learning objectives and does not by itself guarantee generalization.', 'empirical loss; training data; hypothesis class; regularization', 'A learning algorithm can select a model by minimizing empirical loss over observed training data, subject to the assumptions and regularization used. Its valid use is bounded by: Applies to supervised learning objectives and does not by itself guarantee generalization. Key ideas include empirical loss; training data; hypothesis class; regularization.', 'ERM; empirical risk', 'Active'), ('KPR_000090', 'Bias-Variance Trade-off Principle', 'Engineering & Technology', 'Machine Learning', 'Principle', 'Atomic', 'Prediction error can reflect a trade-off among systematic bias, estimator variance, and irreducible noise.', 'Applies to predictive modelling under repeated sampling and is not a universal decomposition for every loss/model without conditions.', 'bias; variance; noise; generalization', 'Prediction error can reflect a trade-off among systematic bias, estimator variance, and irreducible noise. Its valid use is bounded by: Applies to predictive modelling under repeated sampling and is not a universal decomposition for every loss/model without conditions. Key ideas include bias; variance; noise; generalization.', 'bias variance tradeoff; model complexity', 'Active'), ('KPR_000091', 'Regularization Principle', 'Engineering & Technology', 'Machine Learning', 'Principle', 'Atomic', 'Constraining model complexity through a penalty or equivalent structural restriction can reduce overfitting and improve out-of-sample performance.', 'Applies when the regularized objective and penalty are defined; the choice of regularization strength remains data-dependent.', 'complexity control; penalty; overfitting; generalization', 'Links complexity control to generalization rather than treating regularization as a specific algorithm.', 'regularization; complexity penalty', 'Active'), ('KPR_000092', 'No-Free-Lunch Theorem for Optimization', 'Engineering & Technology', 'Machine Learning', 'Theorem', 'Atomic', 'Without assumptions about the problem distribution, averaged performance across all possible problems cannot make one optimization algorithm universally superior to all others.', 'Scope is theoretical and depends on the specified averaging assumptions; it does not say all algorithms perform identically on real datasets.', 'problem distribution; inductive assumptions; algorithm performance', 'Establishes the importance of inductive bias and problem structure in algorithm selection.', 'no free lunch theorem; NFLT', 'Active'), ('KPR_000094', 'Impossibility of Deterministic Consensus in Asynchronous Systems', 'Engineering & Technology', 'Distributed Systems', 'Theorem', 'Atomic', 'In a purely asynchronous distributed system with even one possible crash failure, no deterministic consensus protocol can guarantee termination in all executions.', 'Applies to the FLP model and should not be generalized to partially synchronous systems or randomized algorithms.', 'asynchrony; crash failure; consensus; termination', 'In a purely asynchronous distributed system with even one possible crash failure, no deterministic consensus protocol can guarantee termination in all executions. Its valid use is bounded by: Applies to the FLP model and should not be generalized to partially synchronous systems or randomized algorithms. Key ideas include asynchrony; crash failure; consensus; termination.', 'FLP impossibility; consensus impossibility', 'Active'), ('KPR_000098', 'Water-Cement Ratio Principle', 'Engineering & Technology', 'Concrete Technology', 'Principle', 'Atomic', 'For a given concrete system and curing regime, the water-to-cementitious-material ratio strongly influences hydration, porosity, strength, and durability.', 'Applies to specified materials, mixture proportions, curing and age; it is not a universal one-variable predictor of every concrete property.', 'water-cement ratio; hydration; porosity; strength; durability', 'For a given concrete system and curing regime, the water-to-cementitious-material ratio strongly influences hydration, porosity, strength, and durability. Its valid use is bounded by: Applies to specified materials, mixture proportions, curing and age; it is not a universal one-variable predictor of every concrete property. Key ideas include water-cement ratio; hydration; porosity; strength; durability.', 'water-cement ratio law; Abrams'' law', 'Active'), ('KPR_000099', 'Abrams'' Law', 'Engineering & Technology', 'Concrete Technology', 'Law', 'Atomic', 'For comparable concrete materials and curing conditions, compressive strength varies systematically with the water-cement ratio, commonly represented by an empirical inverse relationship.', 'Applies within the material, age, curing and mixture ranges for which the empirical relation is established.', 'compressive strength; water-cement ratio; empirical relationship', 'For comparable concrete materials and curing conditions, compressive strength varies systematically with the water-cement ratio, commonly represented by an empirical inverse relationship. Its valid use is bounded by: Applies within the material, age, curing and mixture ranges for which the empirical relation is established. Key ideas include compressive strength; water-cement ratio; empirical relationship.', 'Abrams law; compressive strength; water-cement ratio; empirical relationship', 'Active'), ('KPR_000100', 'Rule of Mixtures', 'Engineering & Technology', 'Engineering Materials', 'Rule', 'Atomic', 'For specified composite assumptions, an effective property can be estimated from constituent properties weighted by their volume fractions.', 'Applies to properties and loading directions for which the assumed mixture model is appropriate.', 'volume fraction; constituent properties; composite property', 'For specified composite assumptions, an effective property can be estimated from constituent properties weighted by their volume fractions. Its valid use is bounded by: Applies to properties and loading directions for which the assumed mixture model is appropriate. Key ideas include volume fraction; constituent properties; composite property.', 'rule of mixtures; volume fraction; constituent properties; composite property', 'Active'), ('KPR_000102', 'Darcy-Buckingham Law', 'Engineering & Technology', 'Water Resources Engineering', 'Law', 'Atomic', 'The Darcy-Buckingham law relates water flux in variably saturated porous media to the gradient of total hydraulic potential through an unsaturated hydraulic conductivity that depends on soil water state.', 'Applies primarily to water flow in unsaturated or variably saturated porous media within the continuum and constitutive assumptions of the Darcy-Buckingham formulation; hydraulic conductivity may depend on pressure head or water content, and preferential or strongly non-Darcian flow requires additional treatment.', 'Water flux; total hydraulic potential gradient; unsaturated hydraulic conductivity; porous-media flow', 'The Darcy-Buckingham law extends Darcy-type flux-gradient reasoning to unsaturated soil water flow by allowing hydraulic conductivity to vary with the soil water state. It forms a constitutive component of variably saturated flow models such as the Richards equation.', 'Darcy-Buckingham law; unsaturated Darcy law; unsaturated water flux; hydraulic potential gradient', 'Active'), ('KPR_000103', 'Unit Hydrograph Principle', 'Engineering & Technology', 'Water Resources Engineering', 'Principle', 'Atomic', 'For a linear time-invariant catchment model, direct runoff response to a specified unit effective rainfall pulse can be superposed and scaled to represent other effective rainfall inputs.', 'Applies under the assumptions of linearity and time invariance used by unit-hydrograph theory.', 'effective rainfall; direct runoff; convolution; linearity', 'For a linear time-invariant catchment model, direct runoff response to a specified unit effective rainfall pulse can be superposed and scaled to represent other effective rainfall inputs. Its valid use is bounded by: Applies under the assumptions of linearity and time invariance used by unit-hydrograph theory. Key ideas include effective rainfall; direct runoff; convolution; linearity.', 'unit hydrograph principle; effective rainfall; direct runoff; convolution; linearity', 'Active'), ('KPR_000104', 'Uniformitarianism Principle', 'Engineering & Technology', 'Engineering Geology', 'Principle', 'Atomic', 'Geological processes operating today provide a basis for interpreting past geological features, subject to changes in rates, environments and boundary conditions.', 'Applies to geological interpretation without assuming that past rates and conditions were identical to present ones.', 'geological processes; present; past; interpretation', 'Geological processes operating today provide a basis for interpreting past geological features, subject to changes in rates, environments and boundary conditions. Its valid use is bounded by: Applies to geological interpretation without assuming that past rates and conditions were identical to present ones. Key ideas include geological processes; present; past; interpretation.', 'uniformitarianism; actualism', 'Active'), ('KPR_000105', 'Superposition Principle in Stratigraphy', 'Engineering & Technology', 'Engineering Geology', 'Principle', 'Atomic', 'In an undisturbed sequence of sedimentary strata, older layers generally underlie younger layers.', 'Applies to sedimentary sequences that have not been overturned or otherwise structurally disrupted.', 'stratigraphic order; relative age; sedimentary layers', 'In an undisturbed sequence of sedimentary strata, older layers generally underlie younger layers. Its valid use is bounded by: Applies to sedimentary sequences that have not been overturned or otherwise structurally disrupted. Key ideas include stratigraphic order; relative age; sedimentary layers.', 'law of superposition; stratigraphy', 'Active'), ('KPR_000106', 'Design-for-Manufacture Principle', 'Engineering & Technology', 'CAD/CAM', 'Principle', 'Atomic', 'Product geometry and specifications should be developed with manufacturing processes, tolerances, material behaviour and production constraints considered from the outset.', 'Applies to design decisions intended for manufacturability; exact rules depend on process and production context.', 'manufacturability; tolerances; process constraints; design', 'Product geometry and specifications should be developed with manufacturing processes, tolerances, material behaviour and production constraints considered from the outset. Its valid use is bounded by: Applies to design decisions intended for manufacturability; exact rules depend on process and production context. Key ideas include manufacturability; tolerances; process constraints; design.', 'DFM; design for manufacture', 'Active') ON CONFLICT DO NOTHING;